drops = []

for drop in drops_data:
    data = drop.split("\n")
    things = {}
    for dp in data:
        vars = dp.split(" ")
        for v in vars:
            vn, vv = v.split("=")
            if not vn in things:
                things[vn] = []
            things[vn].append(eval(vv))

    drops.append(things)

def plot(var, drop):
    xs = range(len(drops[drop][var]))
    plt.plot(xs, drops[drop][var], label=var)

for var in ["dh", "spd", "scap", "svol"]:
    plot(var, 0)

plt.legend()
plt.show()
